architecture.h4_f:
msg = CBOR{v:1, text, answer_to, sent_at}
ct = AES-GCM-256-Encrypt(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, text, answer_to?, thread_id?, bahsediliyor mu?, sent_at}
ct = AES-GCM-256-Encrypt(oda_anahtarı, nonce, pt, aad=hex(oda_id))
tel = CBOR{
  v: 1,
  şifreli metin: hex(ct), // değişken uzunluk
  bir kez: hex(12 B),
  sender_pseudo: hex(16 B),
  gönderilen_at: unix_ms
}

cryptoWire.h5_f:
dış = CBOR{
  kaynak_düğüm: hex32,
  hedef_kullanıcı: int64,
  iç_şifre metni: bayt,
  inner_nonce: bayt,
  gönderilen_at: unix_ms
}
sig = Ed25519-Sign(kaynak_özel, dış)
POST /federation/deliver { zarf: dış, imza: hex64 }

auth.h1_f:
POST /api/authentication/register
  { kullanıcı adı, şifre, x25519_public_key, display_name, telefon?, e-posta?, avatar_emoji }

Yanıt 201 Oluşturuldu:
  { erişim_belirteci, yenileme_belirteci, kullanıcı_kimliği, kullanıcı adı, ... }

auth.h3_f:
erişim_token yükü:
  { sub: user_id, jti: devices_id, type: "erişim", exp: şimdi + 15dk }
yenileme_token yükü:
  { sub: user_id, jti: cihaz_id, type: "yenile", exp: şimdi + 30d }

HS256-imzalı, .env'den düğümün 64 baytlık sırrıyla imzalandı

auth.h4_f:
Register_begin(): meydan okuma = rand(32)
                    seçenekler = { rp.id, user.id, pubKeyCredParams, meydan okuma }
                    iade seçenekleri

Register_finish(doğrulama):
  TPM / Secure Enclave kökü CA'ye göre doğrulamayı doğrulayın
  mağaza { kimlik bilgisi_kimliği, genel_anahtar, sayaç: 0 }

auth.h7_f:
POST /api/authentication/qr/begin
  → { tek seferlik: 128 bit onaltılık, ttl: 60 }
QR yük = { tek seferlik, kullanıcı_kimliği, sunucu: "https://node.example" }

POST /api/authentication/qr/verify { bir kez }
  → yeni cihaz kaydedildi; JWT'ler geri döndü.

rooms.h6_f:
gönderen_pseudo = HMAC-SHA256(oda_pseudo_tuz, gönderen_kimliği)[:16] // 32 onaltılık
şifreli metin = AES-GCM-Şifreleme(oda_anahtarı, tek seferlik, CBOR_payload, aad=oda_id)

Çıkış çerçevesi: { type:"m", Room, msg:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {dosya adı, boyut, chunk_size_hint}
            ← {upload_id, chunk_size}
chunk PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bayt>
            ← 204
finalize POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {dosya_id, url}
TTL tamamlanmamış durumda: 24 saat

files.h4_f:
red_listesi = {
  "uygulama/x-dosexec",
  "uygulama/x-paylaşılanlib",
  "uygulama/x-mach-ikili",
}
eğer magic.from_buffer(buf[:1024]) indent_list'te: 415 değerini döndür

presence.h1_f:
istemci: ilk tuş vuruşunda → gönder {type:"t", state:"start"}
         durum değişmediği sürece 3 saniye boyunca gönderim yapılmaz
         Son tuş vuruşundan 10 saniye sonra → gönder {type:"t", state:"stop"}
alıcı: eğer hiçbir "durdurma" gelmezse, son "başlatma"dan 10 saniye sonra otomatik durdurma

calls.h1_f:
POST /api/calls/{room_id}/start {video, ses} → call_id
WS yayın {type:"c", kind:"invite", call_id}
WS yayın {type:"c", tür:"teklif", sdp}
WS yayın {type:"c", tür:"answer", sdp}
WS yayın {type:"c", tür:"aday",ice} × N
POST /api/calls/{call_id}/end

federation.h2_f:
zarf = {
  kaynak_node: hex32,
  hedef_kullanıcı: int64,
  iç_şifre metni: bayt,
  inner_nonce : bayt,
  gönderilen_at : unix_ms,
}
sig = Ed25519Sign(source_priv, CBOR(zarf))
POST /federation/deliver { zarf, imza }

stealth.h2_f:
ClientHello baytları = chrome_120_template ile {
  rastgele = bizim rastgelemiz,
  sunucu_adı = ana makine adımız (veya ECH-sarılmış),
  session_id = oturum kimliğimiz,
}
JA4 = t13d_xxxx_xxxx_xxxx (mevcut Chrome kararlı sürümüyle eşleşir)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {isim: x.vortexx.sol}
ECH: ClientHello.extensions += şifreli_sni(public_key_from_HTTPS_record)
DGA: alan(t) = base32( SHA256(seed ∥ YYYY-MM-DD) )[:16] + ".example"

push.h4_f:
iOS NSE: didReceive(request) { decrypt(request.content.userInfo) }
Android FCM: onMessageReceived(remoteMessage) { decrypt(remoteMessage.data) }
Web SW: self.addEventListener('push', e => decrypt(e.data))

controller.h2_f:
araç =sign_tool
giriş = kaynak ağacı, anahtarlar/release.key
manifest = {
  sürüm: "0.1.0",
  yerleşik_at: unix_ms,
  dosyalar: [{yol, sha256, boyut}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(manifest))
çıktı = INTEGRITY.sig.json = {manifest, Signed_by: pub_hex, sig: sig_hex}

bots.h1_f:
oluştur: POST /api/bots {kullanıcı adı, görünen_adı, kod}
          → {bot_id, token, pubkey}
çalıştır: süreç içi (düğüm içindeki eşyordam)
      OR harici (uzun anket /api/bots/{id}/updates, token-auth'd)
mesaj: {metin, imza: Ed25519-Sign(bot_priv, canonical_msg)}

bots.h2_f:
açık /başla {
  "Hoşgeldin {ctx.first_name}" ifadesini söyle
}
/add <öğe> {
  durum.list = (durum.liste veya []) + [ctx.args.item]
  emit "Eklendi: {ctx.args.item}"
}

security.h4_f:
canary.txt (günlük):
  {tarih, imza: Ed25519-Sign(release_priv, date)}
istemci doğruluyor → yok veya geçersiz ⇒ uzlaşmadan şüpheleniliyor

acil durum:
  admin POST /api/admin/revoke-all {sebep}
  düğüm yayınları {type:"n", event:"compromise", Reason}
  istemciler anahtarları siler, yeniden önyüklemeyi zorlar

