GET /v1/entries → [{protokol, url}, …]
GET /v1/aynalar → [denetleyici_url'si, …]

fcm.h1_f:
POST https://fcm.googleapis.com/v1/projects/<project>/messages:send
Yetkilendirme: Taşıyıcı <oauth2_token>
Gövde: {message: {token: <device>, data: {...sealed...}, android: {collapse_key}}}

federation.h1_f:
zarf = {source_node, target_user, inner_ct, inner_nonce, sent_at}
sig = Ed25519-Sign(source_priv, CBOR(zarf))
POST /federation/deliver {zarf, imza}
B şunu doğruluyor: federasyonlara karşı imza[source_node].pubkey

fts5.h1_f:
CREATE VIRTUAL TABLE mesajlar_fts USING fts5(
  içerik, -- belirtilmiş sütun
  oda_kimliği UNINDEXED,
  tokenize = 'unicode61 kaldır_diacritics 2'
);
sorgu: SELECT satır kimliği FROM message_fts WHERE içerik MATCH 'foo'

prekey.h1_f:
paket = {
  kimlik_pk,
  Signed_prekey_pk,
  Signed_prekey_sig = Ed25519-Sign(identity_priv,signed_prekey_pk),
  one_time_prekeys: [pk_0, pk_1, ..., pk_9]
}

vapid.h1_f:
VAPID anahtarlar: düğüm başına Ed25519 anahtar çifti
işaret JWT: {aud: Push_service_origin, exp: şimdi + 12h, sub: mailto:ops@example}
push istek başlıkları: Yetkilendirme: vapid t=<jwt>, k=<vapid_public_key>
